#include <errno.h>
#include <pthread.h>
#include <threads.h>
#include <time.h>

#include <zephyr/sys/util.h>

int thrd_create(thrd_t *thr, thrd_start_t func, void *arg)
{
	int ret;

	/*
	 * Note: technically, a function pointer returning an int is not directly
	 * convertible to one returning a void *, however on standard ABIs this works
	 * or requires a wrapper.
	 */
	ret = pthread_create(thr, NULL, (void *(*)(void *))func, arg);
	switch (ret) {
	case 0:
		return thrd_success;
	case EAGAIN:
	case ENOMEM:
		return thrd_nomem;
	default:
		return thrd_error;
	}
}

thrd_t thrd_current(void)
{
	return pthread_self();
}

int thrd_detach(thrd_t thr)
{
	if (pthread_detach(thr) != 0) {
		return thrd_error;
	}

	return thrd_success;
}

int thrd_equal(thrd_t lhs, thrd_t rhs)
{
	return pthread_equal(lhs, rhs);
}

FUNC_NORETURN void thrd_exit(int res)
{
	pthread_exit(INT_TO_POINTER(res));
}

int thrd_join(thrd_t thr, int *res)
{
	void *ret;

	if (pthread_join(thr, &ret) != 0) {
		return thrd_error;
	}

	if (res != NULL) {
		*res = POINTER_TO_INT(ret);
	}

	return thrd_success;
}

int thrd_sleep(const struct timespec *duration, struct timespec *remaining)
{
	int ret = nanosleep(duration, remaining);

	if (ret < 0) {
		if (errno == EINTR) {
			return -1;
		}
		return -2;
	}

	return 0;
}

void thrd_yield(void)
{
	(void)sched_yield();
}
